package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarArchiveOutputStream_write_TriageGen0Test {

    private ByteArrayOutputStream baos;
    private TarArchiveOutputStream tarOut;
    private static final int BLOCK_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        baos = new ByteArrayOutputStream();
        // Using default block size 512
        tarOut = new TarArchiveOutputStream(baos, BLOCK_SIZE);
    }

    @Test
    public void testWrite_ExceedsSize() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        // We need to simulate the state where currSize is set. 
        // In actual TarArchiveOutputStream, putArchiveEntry sets the header.
        tarOut.putArchiveEntry(entry);

        // Manually manipulate or use a known small size if possible.
        // Since we can't easily inject currSize without reflection, 
        // we rely on the fact that the entry header defines the size.
        // However, the entry size is 0 by default.

        byte[] data = new byte[10];
        try {
            tarOut.write(data, 0, 10);
            Assert.fail("Should have thrown IOException due to size mismatch");
        } catch (IOException e) {
            Assert.assertTrue(e.getMessage().contains("exceeds size"));
        }
    }

    @Test
    public void testWrite_SmallWrite_AssemblesBuffer() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(100);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[100];
        for (int i = 0; i < 100; i++) data[i] = (byte) i;

        // Write in small chunks to trigger assemLen > 0 logic
        // Chunk 1: 40 bytes
        tarOut.write(data, 0, 40);
        // Chunk 2: 40 bytes
        tarOut.write(data, 40, 40);
        // Chunk 3: 20 bytes (This should trigger the (assemLen + numToWrite) >= recordBuf.length logic if recordBuf is 512)
        // Wait, if recordBuf is 512, 40+40+20 = 100, which is < 512.
        // It will stay in assemBuf until the end or until it hits 512.

        tarOut.closeArchiveEntry();
        tarOut.finish();
        tarOut.close();

        // Verification is complex due to Tar format, but we ensure no exception and logic flow.
        Assert.assertTrue(baos.size() > 0);
    }

    @Test
    public void testWrite_FullRecordWrite() throws IOException {
        int size = BLOCK_SIZE * 2;
        TarArchiveEntry entry = new TarArchiveEntry("large.bin");
        entry.setSize(size);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[size];
        for (int i = 0; i < size; i++) data[i] = (byte) (i % 128);

        // Write exactly one block size to trigger the while(numToWrite > 0) loop and buffer.writeRecord(wBuf, wOffset)
        tarOut.write(data, 0, BLOCK_SIZE);

        // Write the second block
        tarOut.write(data, BLOCK_SIZE, BLOCK_SIZE);

        tarOut.closeArchiveEntry();
        tarOut.finish();
        tarOut.close();

        Assert.assertTrue(baos.size() >= size);
    }

    @Test
    public void testWrite_AssembleAndFlushFullRecord() throws IOException {
        // Use a custom record size to force the "assemLen + numToWrite >= recordBuf.length" branch
        // Let's assume recordBuf is 512.
        int customRecordSize = 100; 
        // Note: TarArchiveOutputStream constructor with recordSize is used.
        // But the provided code's logic uses recordBuf.length.

        // To trigger: (assemLen + numToWrite) >= recordBuf.length
        // We need assemLen to be > 0.

        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(300);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[300];

        // 1. Write 400 bytes (if we could) to trigger the 'else' (assemLen += numToWrite)
        // But we are capped by entry size.

        // Step 1: Fill assemBuf partially
        tarOut.write(data, 0, 400); // This will actually enter the 'while' loop because 400 < 512 is false? 
        // No, if numToWrite (400) < recordBuf.length (512), it goes to the 'if (numToWrite < recordBuf.length)' inside while.

        tarOut.closeArchiveEntry();
        tarOut.finish();
        tarOut.close();
    }

    @Test
    public void testWrite_TriggerAssembleBufferFull() throws IOException {
        // This test targets the branch: if ((assemLen + numToWrite) >= recordBuf.length)
        // We need to create a scenario where assemLen > 0, then add more to reach recordBuf.length

        // We'll use a small record size if the constructor allows, but standard is 512.
        // Let's simulate a large write that fills assemBuf and then another that pushes it over.

        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(1000);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[1000];

        // First write: 300 bytes. 
        // Goes to: while(numToWrite > 0) -> if (numToWrite < 512) -> assemLen becomes 300.
        tarOut.write(data, 0, 300);

        // Second write: 300 bytes.
        // assemLen (300) + numToWrite (300) = 600. 600 >= 512.
        // This triggers: if ((assemLen + numToWrite) >= recordBuf.length)
        tarOut.write(data, 300, 300);

        // Remaining bytes
        tarOut.write(data, 600, 400);

        tarOut.closeArchiveEntry();
        tarOut.finish();
        tarOut.close();

        Assert.assertTrue(baos.size() > 0);
    }

    @Test
    public void testWrite_ZeroBytes() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("empty.txt");
        entry.setSize(0);
        tarOut.putArchiveEntry(entry);

        // Should not throw exception or do anything
        tarOut.write(new byte[10], 0, 0);

        tarOut.closeArchiveEntry();
        tarOut.finish();
        tarOut.close();

        // Check that we still produced a header
        Assert.assertTrue(baos.size() > 0);
    }
}
